async def act(page):
    # Continue from current page state. Wait for network idle so the form is ready.
    await page.wait_for_load_state("networkidle")

    async def count(loc):
        return await loc.count()

    # Scope to the main address table (first table on the page)
    table = page.get_by_role("table").first()

    # 1) Set City -> "Dallas"
    # Prefer the specific row that contains the current value (City * Miami Beach)
    city_row = table.get_by_role("row", name="City * Miami Beach")
    if await count(city_row) > 0:
        city_tb = city_row.get_by_role("textbox", name="City *")
        if await count(city_tb) > 0:
            await city_tb.first().fill("Dallas")
        else:
            any_city_tb = city_row.get_by_role("textbox")
            if await count(any_city_tb) > 0:
                await any_city_tb.first().fill("Dallas")
    else:
        # Global fallback for labeled textbox
        global_city = page.get_by_role("textbox", name="City *")
        if await count(global_city) > 0:
            await global_city.first().fill("Dallas")

    # 2) Set State/Province -> "Texas" (prefer combobox select_option)
    state_row = table.get_by_role("row", name="State/Province * Florida")
    if await count(state_row) > 0:
        state_cb = state_row.get_by_role("combobox")
        if await count(state_cb) > 0:
            # Select by visible label
            await state_cb.first().select_option(label="Texas")
    else:
        # Global fallback combobox
        global_state_cb = page.get_by_role("combobox", name="State/Province *")
        if await count(global_state_cb) > 0:
            await global_state_cb.first().select_option(label="Texas")

    # 3) Set Zip/Postal Code -> "75201"
    zip_row = table.get_by_role("row", name="Zip/Postal Code * 33139")
    if await count(zip_row) > 0:
        zip_tb = zip_row.get_by_role("textbox", name="Zip/Postal Code *")
        if await count(zip_tb) > 0:
            await zip_tb.first().fill("75201")
        else:
            any_zip_tb = zip_row.get_by_role("textbox")
            if await count(any_zip_tb) > 0:
                await any_zip_tb.first().fill("75201")
    else:
        global_zip = page.get_by_role("textbox", name="Zip/Postal Code *")
        if await count(global_zip) > 0:
            await global_zip.first().fill("75201")

    # 4) Ensure street lines are present (they already show the desired values per the accessibility tree)
    # But we will still set them to be explicit: first line "321 Birch Boulevard", second line "Suite 200"
    street_row = table.get_by_role("row", name="Street Address * 321 Birch Boulevard Suite 200")
    if await count(street_row) > 0:
        street_tbs = street_row.get_by_role("textbox")
        if await count(street_tbs) >= 1:
            await street_tbs.nth(0).fill("321 Birch Boulevard")
        if await count(street_tbs) >= 2:
            await street_tbs.nth(1).fill("Suite 200")
    else:
        # Fallback to labeled textbox or first two textboxes on the page
        global_street = page.get_by_role("textbox", name="Street Address *")
        if await count(global_street) > 0:
            await global_street.first().fill("321 Birch Boulevard")
            if await count(global_street) > 1:
                await global_street.nth(1).fill("Suite 200")
        else:
            all_tbs = page.get_by_role("textbox")
            if await count(all_tbs) >= 1:
                await all_tbs.nth(0).fill("321 Birch Boulevard")
            if await count(all_tbs) >= 2:
                await all_tbs.nth(1).fill("Suite 200")

    # 5) Click Save Order Address (top-level button). This is the final action because it submits the form.
    save_btn = page.get_by_role("button", name="Save Order Address")
    if await count(save_btn) > 0:
        await save_btn.first().click()
        return

    # Fallback: generic Save button
    generic_save = page.get_by_role("button", name="Save")
    if await count(generic_save) > 0:
        await generic_save.first().click()
        return

    # If no save button found, finish without clicking.
    return

